describe("doctests of sympy.series.residues", () => {
  it("residue(1/x, x, 0)", () => {
    const x = new Sym('x');
    expect(sympyStr(residue(pow(x, Rational.of(-1n, 1n, { gcd: 1n })), x, Rational.of(0n, 1n, { gcd: 1n })))).toBe('1');
  });
  it("residue(1/x**2, x, 0)", () => {
    const x = new Sym('x');
    expect(sympyStr(residue(pow(x, Rational.of(-2n, 1n, { gcd: 1n })), x, Rational.of(0n, 1n, { gcd: 1n })))).toBe('0');
  });
  it("residue(2/sin(x), x, 0)", () => {
    const x = new Sym('x');
    expect(sympyStr(residue(mul(Rational.of(2n, 1n, { gcd: 1n }), pow(fn('sin', [x], { evaluate: false }), Rational.of(-1n, 1n, { gcd: 1n }))), x, Rational.of(0n, 1n, { gcd: 1n })))).toBe('2');
  });
});

